      if (html2.includes("Domain not found") || response2.status === 404) {
        return { rawText: "Domain not found" };
      }
      let whoisText2 = "";
      const domainMatch2 = html2.match(/<h2>([^<]+)<\/h2>/i);
      if (domainMatch2) {
        whoisText2 += `Domain Name: ${domainMatch2[1].trim()}
`;
      }
      const fieldsetRegex2 = /<fieldset>\s*<span>([^<]+)<\/span>([\s\S]*?)<\/fieldset>/gi;
      let fieldsetMatch2;
