function parseLKDate(input) {
  const match = input.match(/(\d{1,2})(?:st|nd|rd|th)?\s+([A-Za-z]+)\s*,?\s*(\d{4})/);
  if (!match)
    return "";
  const months = {
    january: "01",
    february: "02",
    march: "03",
    april: "04",
    may: "05",
    june: "06",
    july: "07",
    august: "08",
    september: "09",
    october: "10",
    november: "11",
    december: "12"
  };
  const month = months[match[2].toLowerCase()];
  if (!month)
    return "";
  return `${match[3]}-${month}-${match[1].padStart(2, "0")}`;
}
