// src/config.ts
var CONFIG = {
  /**
   * WHOIS proxy pool JSON URL.
   * The file should return an array of proxy entries:
   *   [{ url: "https://...", label: "...", weight: 1 }, ...]
   *
   * Leave empty ("") to disable WHOIS lookups entirely.
   */
  WHOIS_PROXY_POOL_URL: "https://yangkexi.cn/json/pages_whois_server.json",
  /**
   * Allow the caller to override the pool through the `proxy_pool` query
   * parameter. Set to false to always use WHOIS_PROXY_POOL_URL.
   */
  ALLOW_CUSTOM_PROXY_POOL: true
};

// src/api.ts
function cleanDomain(input) {
  let domain = input.trim();
  if (!domain)
    return "";
  domain = domain.replace(/\s+/g, "").replace(/\.{2,}/g, ".").replace(/^\.+|\.+$/g, "");
  try {
    const url = new URL(domain);
    if (url.hostname)
      domain = url.hostname;
  } catch {
  }
  return domain;
}
function isAllowedProxyPoolUrl(raw) {
  let url;
  try {
    url = new URL(raw);
  } catch {
    return false;
  }
  if (url.protocol !== "http:" && url.protocol !== "https:")
    return false;
  const host = url.hostname.toLowerCase().replace(/^\[|\]$/g, "");
  if (!host)
    return false;
  if (host === "localhost" || host.endsWith(".localhost") || host.endsWith(".internal") || host === "::1" || host === "0.0.0.0") {
    return false;
  }
  if (/^127\./.test(host))
    return false;
  if (/^10\./.test(host))
    return false;
  if (/^192\.168\./.test(host))
    return false;
  if (/^169\.254\./.test(host))
    return false;
  const private172 = host.match(/^172\.(\d+)\./);
  if (private172) {
    const second = Number(private172[1]);
    if (second >= 16 && second <= 31)
      return false;
  }
  return true;
}
async function lookup(rawDomain, options) {
  const domain = cleanDomain(rawDomain);
  if (!domain) {
    return { code: 1, msg: "The 'domain' parameter is required.", data: null };
  }
  const parsed = parseDomain(domain);
  if (!parsed) {
    return { code: 1, msg: `'${domain}' is not a valid domain.`, data: null };
  }
  const { registrableDomain, suffix } = parsed;
  const asciiSuffix = toAscii(suffix);
  const requestedPool = options?.proxyPoolUrl;
  if (requestedPool) {
    if (!CONFIG.ALLOW_CUSTOM_PROXY_POOL) {
      return { code: 1, msg: "Custom proxy pools are disabled.", data: null };
    }
    if (!isAllowedProxyPoolUrl(requestedPool)) {
      return {
        code: 1,
        msg: "The 'proxy_pool' parameter must be a public http(s) URL.",
        data: null
      };
    }
  }
  const proxyPoolUrl = requestedPool || CONFIG.WHOIS_PROXY_POOL_URL || void 0;
  const rdapServer = findRdapServer(suffix);
  if (rdapServer) {
    try {
      const rdapResponse = await fetchRdap(rdapServer, registrableDomain);
      const result = parseRdap(suffix, rdapResponse.code, rdapResponse.data);
      if (hasGoodResult(result)) {
        return {
          code: 0,
          msg: "Query successful",
          data: result,
          rawRdap: rdapResponse.data,
          sourceUsed: "rdap"
        };
      }
    } catch {
    }
  }
  if (hasWhoisServer(suffix) && proxyPoolUrl) {
    try {
      const whoisResponse = await fetchWhoisViaProxy(proxyPoolUrl, registrableDomain, suffix);
      if (whoisResponse) {
        const result = parseWhoisText(whoisResponse.rawText);
        if (hasGoodResult(result)) {
          return {
            code: 0,
            msg: "Query successful",
            data: result,
            rawWhois: whoisResponse.rawText,
            sourceUsed: "whois"
          };
        }
      }
    } catch {
    }
  }
  const webTlds2 = tld_web_default;
  if (webTlds2.includes(suffix) || webTlds2.includes(asciiSuffix)) {
    try {
      const scraperResult = await fetchViaWebScraper(registrableDomain, asciiSuffix);
      if (scraperResult) {
        const result = parseWhoisText(scraperResult.rawText);
        if (hasGoodResult(result)) {
          return {
            code: 0,
            msg: "Query successful",
            data: result,
            rawWhois: scraperResult.rawText,
            sourceUsed: "web"
          };
        }
      }
    } catch {
    }
  }
  const availableSources = [];
  if (rdapServer)
    availableSources.push("RDAP");
  if (hasWhoisServer(suffix) && proxyPoolUrl)
    availableSources.push("WHOIS");
  if (webTlds2.includes(suffix) || webTlds2.includes(asciiSuffix))
    availableSources.push("Web");
  if (availableSources.length === 0) {
    return {
      code: 1,
      msg: `No lookup source available for '${registrableDomain}'.`,
      data: null
    };
  }
  return {
    code: 1,
    msg: `All lookup sources failed for '${registrableDomain}'. Tried: ${availableSources.join(", ")}.`,
    data: null
  };
}
function hasGoodResult(r) {
  if (!r)
    return false;
  if (r.reserved)
    return true;
  if (r.registered && !r.unknown)
    return true;
  if (!r.registered && !r.unknown)
    return true;
  return false;
}

// src/handler.ts
async function handleApiRequest(url) {
  const domain = url.searchParams.get("domain") || "";
  const proxyPoolUrl = url.searchParams.get("proxy_pool") || void 0;
  const options = {};
  if (proxyPoolUrl) {
    options.proxyPoolUrl = proxyPoolUrl;
  }
  try {
    const result = await lookup(domain, options);
    return new Response(JSON.stringify(result), {
      headers: {
        "content-type": "application/json;charset=UTF-8",
        "access-control-allow-origin": "*",
        "cache-control": "public, max-age=300"
      }
    });
  } catch (e) {
    const errorResponse = {
      code: 1,
      msg: e?.message || "Internal error",
      data: null
    };
    return new Response(JSON.stringify(errorResponse), {
      status: 500,
      headers: {
        "content-type": "application/json;charset=UTF-8",
        "access-control-allow-origin": "*"
      }
    });
  }
}
function handleOptions() {
  return new Response(null, {
    status: 204,
    headers: {
      "access-control-allow-origin": "*",
      "access-control-allow-methods": "GET, OPTIONS",
      "access-control-allow-headers": "content-type",
      "access-control-max-age": "86400"
    }
  });
}

// src/edgeone/lookup.ts
async function onRequest(context) {
  if (context.request.method === "OPTIONS") {
    return handleOptions();
  }
  return handleApiRequest(new URL(context.request.url));
}
